toolScript:
// --- GAME CONFIG & STATE ---
        const EASY_TARGETS = [
            'United States', 'Earth', 'Biology', 'World War II', 'Internet', 'Music',
            'Science', 'History', 'Mathematics', 'Art', 'Technology', 'Literature',
            'Psychology', 'Philosophy', 'Physics', 'Chemistry', 'Europe', 'Asia',
            'Africa', 'Democracy', 'Computer', 'Movie', 'Nature'
        ];
        const gameState = {
            difficulty: 'moderate',
            startTopic: null,
            targetTopic: null,
            targetSummary: "Loading definition...",
            currentTopic: null,
            clicks: 0,
            startTime: null,
            timerInterval: null,
            history: [],
            isPlaying: false,
            // Resource Limits
            maxHints: 3,
            hintsRemaining: 3,
            maxBacktracks: 3,
            backtracksRemaining: 3,
            penaltySeconds: 0,
            lastClickTime: 0,
            streak: 0
        };
        const UI = {
            startScreen: document.getElementById('start-screen'),
            loader: document.getElementById('loader'),
            content: document.getElementById('content-area'),
            viewport: document.getElementById('wiki-viewport'),
            currentTitle: document.getElementById('current-title'),
            targetDisplay: document.getElementById('target-display'),
            clickCount: document.getElementById('click-count'),
            timer: document.getElementById('timer'),
            winOverlay: document.getElementById('win-overlay'),
            sideStart: document.getElementById('side-start'),
            sideTarget: document.getElementById('side-target'),
            finalClicks: document.getElementById('final-clicks'),
            finalTime: document.getElementById('final-time'),
            hintBtn: document.getElementById('btn-hint'),
            hintsCount: document.getElementById('hints-remaining'),
            hintBar: document.getElementById('hint-bar'),
            hintLabel: document.getElementById('hint-label'),
            backBtn: document.getElementById('btn-back'),
            backCount: document.getElementById('back-count'),
            sidebarBacktracks: document.getElementById('sidebar-backtracks'),
            backtrackBar: document.getElementById('backtrack-bar'),
            streakMeter: document.getElementById('streak-meter'),
            streakBar: document.getElementById('streak-bar'),
            tempDisplay: document.getElementById('temp-display'),
            intelModal: document.getElementById('intel-modal'),
            intelTitle: document.getElementById('intel-title'),
            intelDesc: document.getElementById('intel-desc'),
            statusPing: document.getElementById('status-ping'),
            statusDot: document.getElementById('status-dot')
        };
        const API_BASE = "https://en.wikipedia.org/w/api.php";

        function showStartScreen() {
            gameState.isPlaying = false;
            if (gameState.timerInterval) clearInterval(gameState.timerInterval);

            UI.startScreen.classList.remove('hidden');
            UI.content.classList.add('hidden');
            UI.loader.classList.add('hidden');
            UI.winOverlay.classList.add('hidden');

            // Reset HUD presentation
            UI.currentTitle.innerText = "System Ready";
            UI.targetDisplay.innerText = "Awaiting Start...";
            UI.timer.innerText = "0:00";
            UI.clickCount.innerText = "0";
            UI.tempDisplay.innerText = "--";
            UI.sideStart.innerText = "Waiting...";
            UI.sideTarget.innerText = "Waiting...";

            // Set HUD Status to neutral
            UI.statusPing.classList.add('hidden');
            UI.statusDot.classList.replace('bg-green-500', 'bg-slate-400');
            UI.targetDisplay.classList.replace('text-[#EE6C4D]', 'text-slate-500');
            UI.targetDisplay.classList.remove('cursor-help', 'hover:underline', 'hover:text-white');

            // Disable actions
            UI.hintBtn.disabled = true;
            UI.backBtn.disabled = true;
            UI.hintBtn.classList.add('opacity-50');
            UI.backBtn.classList.add('opacity-50');
        }

        // --- DIFFICULTY & INIT ---
        function startGame(level) {
            gameState.difficulty = level;
            switch (level) {
                case 'easy':
                    gameState.maxHints = 5;
                    gameState.maxBacktracks = 5;
                    break;
                case 'moderate':
                    gameState.maxHints = 3;
                    gameState.maxBacktracks = 3;
                    break;
                case 'hard':
                    gameState.maxHints = 1;
                    gameState.maxBacktracks = 1;
                    break;
                case 'extreme':
                    gameState.maxHints = 0;
                    gameState.maxBacktracks = 0;
                    break;
            }
            gameState.hintsRemaining = gameState.maxHints;
            gameState.backtracksRemaining = gameState.maxBacktracks;

            // Hide Start Screen, show loading
            UI.startScreen.classList.add('hidden');
            UI.content.classList.add('hidden');

            initGame();
        }

        async function initGame() {
            UI.loader.classList.remove('hidden');
            gameState.clicks = 0;
            gameState.history = [];
            gameState.penaltySeconds = 0;
            gameState.streak = 0;
            gameState.isPlaying = false;

            updateHUD();
            updateResourcesUI();
            UI.tempDisplay.innerText = "❄️";
            UI.targetDisplay.innerText = "Generating graph...";

            // Set HUD to active
            UI.statusPing.classList.remove('hidden');
            UI.statusDot.classList.replace('bg-slate-400', 'bg-green-500');
            UI.statusPing.classList.replace('bg-slate-400', 'bg-green-400');
            UI.targetDisplay.classList.replace('text-slate-500', 'text-[#EE6C4D]');
            UI.targetDisplay.classList.add('cursor-help', 'hover:underline', 'hover:text-white');

            let start, end;
            start = await getRandomArticle();

            if (gameState.difficulty === 'easy') {
                end = EASY_TARGETS[Math.floor(Math.random() * EASY_TARGETS.length)];
                if (start === end) start = await getRandomArticle();
            } else {
                end = await getRandomArticle();
                if (start === end) {
                    end = await getRandomArticle();
                }
            }

            gameState.startTopic = start;
            gameState.targetTopic = end;

            fetchTargetSummary(end).then(summary => {
                gameState.targetSummary = summary;
            });

            UI.targetDisplay.innerText = end;
            UI.sideStart.innerText = start;
            UI.sideTarget.innerText = end;

            await loadPage(start);

            gameState.startTime = Date.now();
            gameState.lastClickTime = Date.now();
            gameState.isPlaying = true;
            if (gameState.timerInterval) clearInterval(gameState.timerInterval);
            gameState.timerInterval = setInterval(updateTimer, 1000);

            // Reveal content
            UI.loader.classList.add('hidden');
            UI.content.classList.remove('hidden');

            // Enable Actions
            if (gameState.maxHints > 0) {
                UI.hintBtn.disabled = false;
                UI.hintBtn.classList.remove('opacity-50');
            }
        }

        // --- GAME LOGIC ---
        async function getRandomArticle() {
            const params = new URLSearchParams({
                action: 'query',
                list: 'random',
                rnnamespace: 0,
                rnlimit: 1,
                format: 'json',
                origin: '*'
            });
            try {
                const res = await fetch(`${API_BASE}?${params}`);
                const data = await res.json();
                return data.query.random[0].title;
            } catch (e) {
                console.error("API Error", e);
                return "Graph theory"; // Fallback
            }
        }

        async function fetchTargetSummary(title) {
            const params = new URLSearchParams({
                action: 'query',
                format: 'json',
                prop: 'extracts',
                exintro: true,
                explaintext: true,
                titles: title,
                origin: '*'
            });
            try {
                const res = await fetch(`${API_BASE}?${params}`);
                const data = await res.json();
                const pages = data.query.pages;
                const pageId = Object.keys(pages)[0];
                return pages[pageId].extract || "No description available.";
            } catch (e) {
                return "Could not fetch description.";
            }
        }

        async function getPageContent(title) {
            const params = new URLSearchParams({
                action: 'parse',
                page: title,
                prop: 'text',
                format: 'json',
                redirects: 1,
                disablelimitreport: true,
                disableeditsection: true,
                origin: '*'
            });
            try {
                const res = await fetch(`${API_BASE}?${params}`);
                const data = await res.json();
                if (data.error) throw new Error(data.error.info);
                return { title: data.parse.title, html: data.parse.text['*'] };
            } catch (err) {
                console.error(err);
                return null;
            }
        }

        function showTargetIntel() {
            if (!gameState.isPlaying) return;
            UI.intelTitle.innerText = gameState.targetTopic;
            UI.intelDesc.innerText = gameState.targetSummary;
            UI.intelModal.classList.remove('hidden');
        }

        async function loadPage(title) {
            UI.loader.classList.remove('hidden');
            UI.content.classList.add('hidden'); // hide while switching
            UI.viewport.scrollTop = 0;

            const data = await getPageContent(title);
            if (!data) {
                setTimeout(() => loadPage(title), 2000);
                return;
            }

            gameState.currentTopic = data.title;
            if (gameState.history.length === 0 || gameState.history[gameState.history.length - 1] !== data.title) {
                gameState.history.push(data.title);
            }

            UI.currentTitle.innerText = data.title;
            const headerHTML = `<h1 class="text-3xl md:text-4xl font-black mb-6 border-b pb-4 border-slate-200">${data.title}</h1>`;
            UI.content.innerHTML = headerHTML + data.html;

            processLinks();

            UI.loader.classList.add('hidden');
            UI.content.classList.remove('hidden');

            updateResourcesUI();
            checkWinCondition();
        }

        // --- BACKTRACK LOGIC ---
        async function goBack() {
            if (!gameState.isPlaying || gameState.history.length <= 1 || gameState.backtracksRemaining <= 0) return;
            gameState.backtracksRemaining--;

            gameState.history.pop();
            const previousTopic = gameState.history[gameState.history.length - 1];

            UI.loader.classList.remove('hidden');
            UI.content.classList.add('hidden');

            const data = await getPageContent(previousTopic);
            gameState.currentTopic = data.title;
            UI.currentTitle.innerText = data.title;

            const headerHTML = `<h1 class="text-3xl md:text-4xl font-black mb-6 border-b pb-4 border-slate-200">${data.title}</h1>`;
            UI.content.innerHTML = headerHTML + data.html;
            processLinks();

            UI.loader.classList.add('hidden');
            UI.content.classList.remove('hidden');
            updateResourcesUI();
        }

        function processLinks() {
            const links = UI.content.querySelectorAll('a');
            const targetWords = gameState.targetTopic.toLowerCase().split(' ').filter(w => w.length > 3);
            let hasDirectLink = false;
            let keywordMatches = 0;
            let validLinks = 0;

            links.forEach(link => {
                const href = link.getAttribute('href');
                if (!href || !href.startsWith('/wiki/') || href.includes('#') || href.includes(':')) {
                    if (href && (href.includes('Category:') || href.includes('File:') || href.includes('Special:') || href.includes('Help:'))) {
                        link.style.pointerEvents = 'none';
                        link.style.color = '#94a3b8';
                        link.removeAttribute('href');
                        return;
                    }
                    if (href && href.startsWith('#')) return;
                    link.removeAttribute('href');
                    link.style.color = '#94a3b8';
                    link.style.textDecoration = 'none';
                    link.style.cursor = 'default';
                    return;
                }
                const linkTitle = decodeURIComponent(href.replace('/wiki/', '')).replace(/_/g, ' ');
                if (linkTitle.toLowerCase() === gameState.targetTopic.toLowerCase()) {
                    hasDirectLink = true;
                } else {
                    const lowerLink = linkTitle.toLowerCase();
                    if (targetWords.some(word => lowerLink.includes(word))) {
                        keywordMatches++;
                    }
                }
                validLinks++;
                link.onclick = (e) => {
                    e.preventDefault();
                    if (!gameState.isPlaying) return;
                    gameState.clicks++;
                    handleStreak();
                    updateHUD();
                    loadPage(linkTitle);
                };
            });
            updateTemperature(hasDirectLink, keywordMatches, validLinks);
        }

        function updateTemperature(directLink, matches, totalLinks) {
            let signal = "❄️";
            let color = "text-blue-400";
            if (directLink) {
                signal = "🔥";
                color = "text-red-500 animate-pulse";
            } else if (matches > 0) {
                if (matches > 5 || (totalLinks > 0 && matches / totalLinks > 0.05)) {
                    signal = "🌡️";
                    color = "text-orange-500";
                } else {
                    signal = "😐";
                    color = "text-yellow-400";
                }
            }
            UI.tempDisplay.innerText = signal;
            UI.tempDisplay.className = `text-xl md:text-2xl font-mono font-bold ${color}`;
        }

        // --- FLOW STATE SYSTEM ---
        function handleStreak() {
            const now = Date.now();
            const diff = now - gameState.lastClickTime;
            gameState.lastClickTime = now;
            if (diff < 5000) {
                gameState.streak++;
                triggerFlowEffect(true);
            } else {
                gameState.streak = 0;
                triggerFlowEffect(false);
            }
            const maxStreak = 5;
            const percentage = Math.min((gameState.streak / maxStreak) * 100, 100);
            UI.streakMeter.classList.remove('hidden');
            UI.streakMeter.classList.add('opacity-100');
            UI.streakBar.style.width = `${percentage}%`;
            if (gameState.streak >= 3) {
                UI.clickCount.classList.add('streak-fire');
            } else {
                UI.clickCount.classList.remove('streak-fire');
            }
        }

        function triggerFlowEffect(isActive) {
            if (isActive && gameState.streak % 5 === 0) {
                confetti({
                    particleCount: 30,
                    spread: 60,
                    origin: { y: 0.8 },
                    colors: ['#EE6C4D', '#fbbf24']
                });
            }
        }

        // --- HINT SYSTEM ---
        function useHint() {
            if (gameState.hintsRemaining <= 0 || !gameState.isPlaying) return;
            gameState.hintsRemaining--;
            gameState.penaltySeconds += 15;
            updateResourcesUI();

            const links = Array.from(UI.content.querySelectorAll('a[href^="/wiki/"]'));
            if (links.length === 0) return;
            const targetWords = gameState.targetTopic.toLowerCase().split(' ').filter(w => w.length > 3);

            let matches = links.filter(link => {
                const text = link.innerText.toLowerCase();
                return targetWords.some(word => text.includes(word));
            });
            if (matches.length === 0) {
                matches = links.filter(link => {
                    const text = link.innerText;
                    return /\b(19|20)\d{2}\b/.test(text) || ['United States', 'United Kingdom', 'France', 'China', 'Science', 'History'].includes(text);
                });
            }
            if (matches.length === 0) {
                matches = links;
            }

            matches.sort(() => 0.5 - Math.random());
            const hints = matches.slice(0, 3);
            hints.forEach(link => {
                link.classList.add('hint-highlight');
                link.scrollIntoView({ behavior: 'smooth', block: 'center' });
            });

            const toast = document.createElement('div');
            toast.className = 'fixed top-20 right-1/2 transform translate-x-1/2 bg-yellow-500 text-white px-6 py-3 rounded-full shadow-xl z-50 font-bold animate-pulse';
            toast.innerText = "+15s Penalty applied! Hints revealed.";
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 2000);
        }

        function updateResourcesUI() {
            // Update Hints
            UI.hintsCount.innerText = `${gameState.hintsRemaining}/${gameState.maxHints}`;
            UI.hintLabel.innerText = `Hint (${gameState.hintsRemaining})`;
            if (gameState.maxHints > 0) {
                UI.hintBar.style.width = `${(gameState.hintsRemaining / gameState.maxHints) * 100}%`;
            } else {
                UI.hintBar.style.width = '0%';
            }
            if (gameState.hintsRemaining === 0) {
                UI.hintBtn.classList.add('opacity-50', 'cursor-not-allowed');
                UI.hintBtn.disabled = true;
            } else {
                UI.hintBtn.classList.remove('opacity-50', 'cursor-not-allowed');
                UI.hintBtn.disabled = false;
            }

            // Update Backtracks
            UI.backCount.innerText = gameState.backtracksRemaining;
            UI.sidebarBacktracks.innerText = `${gameState.backtracksRemaining}/${gameState.maxBacktracks}`;
            if (gameState.maxBacktracks > 0) {
                UI.backtrackBar.style.width = `${(gameState.backtracksRemaining / gameState.maxBacktracks) * 100}%`;
            } else {
                UI.backtrackBar.style.width = '0%';
            }

            if (gameState.backtracksRemaining <= 0 || gameState.history.length <= 1) {
                UI.backBtn.disabled = true;
                UI.backBtn.classList.add('opacity-50', 'cursor-not-allowed');
            } else {
                UI.backBtn.disabled = false;
                UI.backBtn.classList.remove('opacity-50', 'cursor-not-allowed');
            }
        }

        // --- WIN/LOSE LOGIC ---
        function checkWinCondition() {
            if (gameState.currentTopic.toLowerCase() === gameState.targetTopic.toLowerCase()) {
                endGame();
            }
        }

        function endGame() {
            gameState.isPlaying = false;
            clearInterval(gameState.timerInterval);
            var duration = 3000;
            var end = Date.now() + duration;
            (function frame() {
                confetti({
                    particleCount: 5, angle: 60, spread: 55, origin: { x: 0 }, colors: ['#EE6C4D', '#22c55e']
                });
                confetti({
                    particleCount: 5, angle: 120, spread: 55, origin: { x: 1 }, colors: ['#EE6C4D', '#22c55e']
                });
                if (Date.now() < end) requestAnimationFrame(frame);
            }());

            UI.finalClicks.innerText = gameState.clicks;
            const rawSeconds = Math.floor((Date.now() - gameState.startTime) / 1000);
            const totalSeconds = rawSeconds + gameState.penaltySeconds;
            UI.finalTime.innerText = formatTime(totalSeconds) + (gameState.penaltySeconds > 0 ? ` (+${gameState.penaltySeconds}s pen)` : '');
            UI.winOverlay.classList.remove('hidden');
        }

        function updateTimer() {
            const rawSeconds = Math.floor((Date.now() - gameState.startTime) / 1000);
            UI.timer.innerText = formatTime(rawSeconds);
        }

        function formatTime(seconds) {
            const m = Math.floor(seconds / 60);
            const s = seconds % 60;
            return `${m}:${s < 10 ? '0' : ''}${s}`;
        }

        function updateHUD() {
            UI.clickCount.innerText = gameState.clicks;
        }

        function copyResult() {
            const text = `I raced from "${gameState.startTopic}" to "${gameState.targetTopic}" in ${gameState.clicks} clicks on Wiki Speed Racer (${gameState.difficulty} mode)! 🏎️💨`;
            navigator.clipboard.writeText(text).then(() => alert("Result copied!"));
        }

        // Scroll Logic
        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            showStartScreen();
        });
